create table if not exists public.player_settings(player_id uuid primary key references auth.users(id) on delete cascade,sound_enabled boolean not null default true,music_enabled boolean not null default true,notifications_enabled boolean not null default true,updated_at timestamptz not null default now());
create table if not exists public.notifications(id uuid primary key default gen_random_uuid(),player_id uuid not null references auth.users(id) on delete cascade,title text not null,body text not null,read_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.tournaments(id uuid primary key default gen_random_uuid(),name text not null,starts_at timestamptz not null,ends_at timestamptz not null,status text not null default 'scheduled',created_at timestamptz not null default now(),check(ends_at>starts_at));
create table if not exists public.tournament_entries(tournament_id uuid not null references public.tournaments(id) on delete cascade,player_id uuid not null references auth.users(id) on delete cascade,best_score bigint not null default 0,best_session_id uuid references public.game_sessions(id),updated_at timestamptz not null default now(),primary key(tournament_id,player_id));
create table if not exists public.shared_results(id uuid primary key default gen_random_uuid(),player_id uuid not null references auth.users(id) on delete cascade,session_id uuid references public.game_sessions(id) on delete set null,amount bigint not null,questions_survived smallint not null,correct_count smallint not null,share_token text not null unique,created_at timestamptz not null default now());
alter table public.player_settings enable row level security; alter table public.notifications enable row level security; alter table public.tournaments enable row level security; alter table public.tournament_entries enable row level security; alter table public.shared_results enable row level security;
create policy settings_self on public.player_settings for all using(player_id=auth.uid()) with check(player_id=auth.uid());
create policy notifications_self on public.notifications for select using(player_id=auth.uid());
create policy tournaments_public on public.tournaments for select using(true);
create policy tournament_entries_public on public.tournament_entries for select using(true);
create policy shared_results_public on public.shared_results for select using(true);
